package com.hs.jxc.lgs;
import com.hs.jxc.common.api.*;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.sys.api.Access;
import com.hs.jxc.sys.imports.ImportHandler;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
@Component
public class TransitOpeningImportHandler implements ImportHandler {
 private final JdbcTemplate jdbc;private final LogisticsService logistics;public TransitOpeningImportHandler(JdbcTemplate jdbc,LogisticsService logistics){this.jdbc=jdbc;this.logistics=logistics;}
 public List<String> types(){return List.of("OPENING_TRANSIT");}
 public List<String> columns(String type){return List.of("bookId","warehouseCode","carrierCode","transportMode","refNo","sourceDate","blNo","vessel","voyage","containerNo","sealNo","awbNo","flightNo","lines");}
 private long resolve(String sql,Object...args){var ids=jdbc.queryForList(sql,Long.class,args);if(ids.size()!=1)throw Inputs.bad("本国档案不存在或未启用");return ids.getFirst();}
 @SuppressWarnings("unchecked") public Row validate(Access a,String type,LocalDate cutoff,int number,Map<String,Object> raw){a.require("lgs:shipment:create");if(cutoff==null)throw Inputs.bad("期初在途须填写截止日期");var source=LocalDate.parse(Inputs.required(raw,"sourceDate"));if(source.isAfter(cutoff))throw Inputs.bad("截止日期后的发运不能计入期初");long book=Inputs.id(raw.get("bookId"));if(!a.canBook(book))throw ApiException.notFound();long wh=resolve("SELECT id FROM org_warehouse WHERE country_id=? AND code=? AND status='ENABLED'",a.requireCountry(),Inputs.required(raw,"warehouseCode"));if(!a.scope().all()&&!a.scope().warehouses().contains(wh))throw ApiException.notFound();long carrier=resolve("SELECT id FROM md_logistics_provider WHERE country_id=? AND code=? AND status='ENABLED'",a.requireCountry(),Inputs.required(raw,"carrierCode"));String ref=Inputs.required(raw,"refNo");if(ref.length()>100)throw Inputs.bad("来源编号过长");if(jdbc.queryForObject("SELECT count(*) FROM lgs_shipment WHERE country_id=? AND (doc_no=? OR opening_ref=?)",Integer.class,a.requireCountry(),ref,ref)>0)throw new ApiException(409,"SYS_IMPORT_REFERENCE_EXISTS","在途来源已有系统单据");String mode=Inputs.required(raw,"transportMode");if(!Set.of("SEA","AIR").contains(mode))throw Inputs.bad("运输方式不合法");var v=new LinkedHashMap<String,Object>();for(String key:mode.equals("SEA")?List.of("vessel","voyage","blNo","containerNo","sealNo"):List.of("awbNo","flightNo"))v.put(key,Inputs.required(raw,key));if(!(raw.get("lines") instanceof List<?> ls)||ls.isEmpty())throw Inputs.bad("期初在途须有已审批的期初采购来源行");var lines=new ArrayList<Map<String,Object>>();var keys=new HashSet<Long>();for(var value:ls){if(!(value instanceof Map<?,?>))throw Inputs.bad("来源行格式不正确");var line=(Map<String,Object>)value;var rows=jdbc.queryForList("SELECT l.id,l.base_qty-l.cancelled_qty-l.qualified_qty-l.pending_inspect_qty-l.opening_shipped_qty available FROM pur_order_line l JOIN pur_order p ON p.country_id=l.country_id AND p.id=l.order_id WHERE p.country_id=? AND p.book_id=? AND p.opening_ref=? AND p.cutoff_date=? AND p.status IN ('CONFIRMED','PARTIAL_DELIVERED') AND l.line_no=?",a.requireCountry(),book,Inputs.required(line,"poRefNo"),cutoff,Inputs.id(line.get("lineNo")));if(rows.size()!=1)throw Inputs.bad("采购来源须为同截止日期已审批的期初采购行");long id=((Number)rows.getFirst().get("id")).longValue();if(!keys.add(id))throw Inputs.bad("来源行重复");var qty=Inputs.decimal(line.get("qty"),4,new BigDecimal("999999999999"));if(qty.signum()<=0||qty.compareTo((BigDecimal)rows.getFirst().get("available"))>0)throw Inputs.bad("在途数量超过采购来源未发运数量");lines.add(Map.of("sourceType","OPENING_PURCHASE_LINE","sourceLineId",id,"baseQty",qty));}v.put("bookId",book);v.put("destWarehouseId",wh);v.put("carrierId",carrier);v.put("transportMode",mode);v.put("refNo",ref);v.put("sourceDate",source.toString());v.put("lines",lines);return new Row(number,v,cutoff+":"+ref);}
 public Target apply(RequestContext c,Access a,Batch batch,Row row){long source=jdbc.queryForObject("SELECT id FROM sys_import_row WHERE country_id=? AND batch_id=? AND row_no=?",Long.class,a.requireCountry(),batch.id(),row.rowNo());var result=logistics.importTransit(c,a,row.values(),row.values().get("refNo").toString(),batch.cutoffDate(),LocalDate.parse(row.values().get("sourceDate").toString()),source,ImportHandler.commandKey(batch,row,"transit"));return new Target("SHIPMENT",Inputs.id(result.get("id")));}
}
